// Collect results
let results = [];

for (const item of items) {
  try {
    const inputJson = item.json;
    const body = inputJson.body || inputJson || {};
    const details = body.details || {};

    // 1. TARGET USER
    let targetEmail = body.reporterEmail;
    if (details.onBehalfEmail && details.onBehalfEmail !== "empty") {
      targetEmail = Array.isArray(details.onBehalfEmail) ? details.onBehalfEmail[0] : details.onBehalfEmail;
    }
    if (!targetEmail) targetEmail = "unknown@[your-domain]";

    // 2. PARSE SYSTEM LIST
    let rawSystems = body.systemList;
    let systemsToProcess = [];

    // Scenario A: Array
    if (Array.isArray(rawSystems)) {
      systemsToProcess = rawSystems.map(s => typeof s === 'string' ? s.trim() : JSON.stringify(s));
    }
    // Scenario B: Comma-separated string
    else if (rawSystems && typeof rawSystems === 'string' && rawSystems !== "empty") {
      const protectedString = rawSystems.replace(/\([^)]+\)/g, (m) => m.replace(/,/g, '###COMMA###'));
      systemsToProcess = protectedString.split(',').map(s => s.trim().replace(/###COMMA###/g, ','));
    }
    // Scenario C: Other field
    else if (details.otherSystemName && details.otherSystemName !== "empty") {
      systemsToProcess = [details.otherSystemName];
    }
    else {
      systemsToProcess = ["MISSING_SYSTEM_DATA"];
    }

    systemsToProcess = systemsToProcess.filter(s => s && s.length > 0);

    // 3. BUILD RESULTS
    for (const sysName of systemsToProcess) {
      let extraInfo = "";

      // Add system-specific detail extraction as needed
      // Example: if (sysName.toLowerCase().includes("github") && details.githubOrg) extraInfo = details.githubOrg;

      let finalSysName = sysName;
      if (sysName.toLowerCase().includes("other") && details.otherSystemName) {
        finalSysName = details.otherSystemName;
      }

      results.push({
        json: {
          issueKey: body.issueKey || "NO-KEY",
          targetEmail: targetEmail,
          targetName: body.reporterName,
          system_name_raw: finalSysName,
          system_details: extraInfo,
          permission_level: body.permission || "User"
        }
      });
    }

  } catch (err) {
    results.push({ json: { issueKey: "ERROR", error: err.message } });
  }
}

return results;

return items.map(item => {
  const data = item.json;

  const sys  = data.system_name_raw  || "";
  const det  = data.system_details   || "";
  const perm = data.permission_level || "";

  const searchKey = [sys, det, perm]
    .filter(p => p && p.trim().length > 0)
    .join(" ");

  return {
    json: {
      issueKey:    data.issueKey,
      targetEmail: data.targetEmail,
      targetName:  data.targetName,
      search_key:  searchKey
    }
  };
});

return items.map((item, index) => {
  const jiraNodeData = $('Merge (Jira + Sheet)').all()[index]?.json || {};

  let aiResult = {};
  const rawResponse = item.json.response || item.json.text || (item.json.content?.parts?.[0]?.text) || "";

  try {
    const cleanJsonString = rawResponse
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();

    const parsedData = JSON.parse(cleanJsonString);

    if (parsedData && typeof parsedData === 'object' && !Array.isArray(parsedData)) {
      aiResult = parsedData;
    } else {
      aiResult = {
        matched_license_name: parsedData,
        match_found: false,
        license_id: null,
        note: "AI returned unexpected format (not an object)"
      };
    }
  } catch (error) {
    aiResult = {
      match_found: false,
      matched_license_name: "PARSE_ERROR",
      license_id: null,
      raw_error: error.message,
      raw_input: rawResponse
    };
  }

  return {
    json: {
      "Issue Key":             jiraNodeData.issueKey || "UNKNOWN",
      "User Email":            jiraNodeData.targetEmail,
      "Requested System":      jiraNodeData.search_key,
      "Matched_license_name":  aiResult.matched_license_name || aiResult.foundName || "NOT_FOUND",
      "License ID":            aiResult.license_id || aiResult.foundId || "",
      "Date":                  new Date().toISOString()
    }
  };
});

// Get seats response
const seatsResponse = $input.item.json;

// Get user ID from Snipe-IT response
const targetUserId = $('Get Snipe User').item.json.rows[0].id;

// Get license ID from AI match
const targetLicenseId = $('Parse AI Response').item.json['License ID'];

// Get Jira issue key for the note
const jiraKey = $('Start').item.json.body.issueKey;

// Find a free seat
const seats = seatsResponse.rows || [];
const freeSeat = seats.find(seat =>
  (seat.available_actions && seat.available_actions.checkout === true) ||
  seat.assigned_user === null
);

// No free seats
if (!freeSeat) {
  throw new Error(`ERROR: All ${seats.length} seats for license ID ${targetLicenseId} are taken.`);
}

// Missing required data
if (!targetUserId || !targetLicenseId) {
  throw new Error(`ERROR: Missing data. UserID: ${targetUserId}, LicenseID: ${targetLicenseId}`);
}

// Build note
let noteContent = "Assigned via n8n automated process";
if (jiraKey) {
  noteContent = `[YOUR_JIRA_URL]/browse/${jiraKey}`;
}

return {
  json: {
    seat_id:    freeSeat.id,
    license_id: targetLicenseId,
    user_id:    targetUserId,
    note:       noteContent
  }
};
